import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { FieldError, FormErrorAlert } from "@/components/ui/form-message";
import { scrollToFirstInvalidField } from "@/lib/form-utils";
import { XCircle, Loader2 } from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import { parseApiError } from "@/lib/api-errors";
import { validateBookingComments } from "@/features/reservations/utils/booking-validation";

interface DeclineBookingDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (comments: string) => void;
  isPending: boolean;
  /** The last failed request, shown inside the dialog (field errors under the input, others in a banner). */
  error?: unknown;
}

export function DeclineBookingDialog({
  isOpen,
  onClose,
  onConfirm,
  isPending,
  error,
}: DeclineBookingDialogProps) {
  const [comments, setComments] = useState("");
  const [commentsError, setCommentsError] = useState<string | undefined>();
  const [generalError, setGeneralError] = useState<string | undefined>();
  const { t } = useLanguage();

  useEffect(() => {
    if (!isOpen) {
      setComments("");
      setCommentsError(undefined);
      setGeneralError(undefined);
    }
  }, [isOpen]);

  useEffect(() => {
    if (!error) return;
    const { fieldErrors, generalMessage } = parseApiError(error, {
      t,
      fallbackMessage: t("reservations.messages.declineFailed"),
      fields: ["comments"],
    });
    setCommentsError(fieldErrors.comments);
    setGeneralError(generalMessage);
  }, [error, t]);

  const handleConfirm = () => {
    if (isPending) return;
    // The client is told why the booking was cancelled, so a reason is required.
    const message = validateBookingComments(comments, t, { required: true });
    setCommentsError(message);
    if (message) {
      scrollToFirstInvalidField();
      return;
    }
    setGeneralError(undefined);
    onConfirm(comments.trim());
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && !isPending && onClose()}>
      <DialogContent className="sm:max-w-md bg-white">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-red-600">
            <XCircle className="h-5 w-5" />
            {t("reservations.declineDialog.title")}
          </DialogTitle>
          <DialogDescription>
            {t("reservations.declineDialog.description")}
          </DialogDescription>
        </DialogHeader>
        <div className="py-3 space-y-3">
          <FormErrorAlert message={generalError} />
          <div>
            <label htmlFor="decline-booking-reason" className="text-sm font-medium text-gray-700 mb-1 block">
              {t("reservations.declineDialog.reasonLabel")} <span className="text-red-500">*</span>
            </label>
            <Textarea
              id="decline-booking-reason"
              placeholder={t("reservations.declineDialog.commentsPlaceholder")}
              value={comments}
              onChange={(e) => {
                setComments(e.target.value);
                if (commentsError) setCommentsError(undefined);
              }}
              rows={3}
              className="resize-none"
              disabled={isPending}
              error={!!commentsError}
              aria-invalid={!!commentsError}
            />
            <FieldError message={commentsError} />
          </div>
        </div>
        <DialogFooter>
          <Button
            variant="outline"
            onClick={onClose}
            disabled={isPending}
          >
            {t("reservations.actions.cancel")}
          </Button>
          <Button
            variant="destructive"
            onClick={handleConfirm}
            disabled={isPending}
            className="gap-2 bg-red-600 hover:bg-red-700 text-white"
          >
            {isPending ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <XCircle className="h-4 w-4" />
            )}
            {isPending ? t("reservations.actions.declining") : t("reservations.actions.decline")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
